print("\n正在生成 PDF 文档...")
from fpdf import FPDF

class PDF(FPDF):
    def __init__(self):
        super().__init__('P', 'mm', 'A4')
        # 注册中文字体
        font_dir = os.path.join(os.environ.get('WINDIR', 'C:\\Windows'), 'Fonts')
        msyh_path = os.path.join(font_dir, 'msyh.ttc')
        msyhbd_path = os.path.join(font_dir, 'msyhbd.ttc')
        if os.path.exists(msyh_path):
            self.add_font('MSYH', '', msyh_path, uni=True)
        else:
            # 尝试 simhei 作为备选
            simhei = os.path.join(font_dir, 'simhei.ttf')
            if os.path.exists(simhei):
                self.add_font('MSYH', '', simhei, uni=True)
            else:
                raise RuntimeError("未找到中文字体文件")
        if os.path.exists(msyhbd_path):
            self.add_font('MSYH', 'B', msyhbd_path, uni=True)
        else:
            self.add_font('MSYH', 'B', msyh_path, uni=True)  # 回退到常规
        self.set_auto_page_break(True, 20)

    def header(self):
        if self.page_no() > 2:
            self.set_font('MSYH', '', 8)
            self.set_text_color(150, 150, 150)
            self.cell(0, 5, 'AI测试工程师面试题库 - 650题完整版', align='L')
            self.cell(0, 5, f'第{self.page_no()}页', align='R', new_x="LMARGIN", new_y="NEXT")
            self.line(self.l_margin, self.get_y(), self.w - self.r_margin, self.get_y())
            self.ln(3)

    def footer(self):
        self.set_y(-15)

